const seniorTopics={"daily": ["ny-connects", "ny-aging-directory", "ny-eisep", "ny-caregiver", "ny-nhtd", "ny-independent-living"], "accessibility": ["ny-access-home", "ny-restore", "ny-traid", "ny-nhtd", "ny-independent-living"], "vision": ["ny-vision", "ny-traid"], "hearing": ["ny-relay", "ny-traid"], "memory": ["alz-dementia-support", "ny-caregiver", "ny-eisep"], "costs": ["ny-hiicap", "ny-eisep", "ny-connects"], "rights": ["ny-disability-rights", "ny-ombudsman", "ny-connects"]};
